export const BODY: string = "\n<p>سیچوریشن درست کرنا صرف چند منٹ کا کام ہے۔ آپ تصویر اپ لوڈ کرتے ہیں، سلائیڈر کھینچتے ہیں، رنگ دیکھتے ہیں اور زیادہ رنگین نسخہ ڈاؤن لوڈ کر لیتے ہیں۔</p>\n<p>یہ رہنمائی پورا عمل قدم بہ قدم سمجھاتی ہے۔ اس میں سلائیڈر، فوری پری سیٹس، جلد کے رنگ اور ایکسپورٹ کی ترتیبات شامل ہیں، تاکہ رنگ صاف رہیں۔</p>\n<p>آخر تک آپ پھیکی لینڈ سکیپ کو ٹھیک کر سکیں گے، تیز رنگ والی تصویر کو نرم کر سکیں گے یا رنگین پورٹریٹ کو صاف سیاہ سفید میں بدل سکیں گے، کسی بھی ڈیوائس پر۔ اصل تصویر اس وقت تک رکھیں، جب تک نتیجہ جانچ نہ لیں۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: رنگوں کا اندازہ لگائیں</h2>\n<p>ٹول کھولنے سے پہلے تصویر کو غور سے دیکھیں۔ کیا رنگ پھیکے ہیں، رنگین ہیں یا بہت زیادہ تیز ہیں؟ اس جواب سے معلوم ہوتا ہے کہ سلائیڈر کس سمت جانا چاہیے۔</p>\n<p>پھیکی تصویر کو دس سے پچیس فیصد کا مثبت اضافہ چاہیے۔ بہت تیز رنگ والی تصویر کو رنگوں کو قدرتی کی طرف واپس لانے کے لیے منفی حرکت چاہیے۔</p>\n<p>یہ بھی دیکھیں کہ تصویر بہت اندھیری یا بہت پھیکی تو نہیں۔ پھیکی اور اندھیری تصویر کو پہلے چمک چاہیے، کیونکہ صرف سیچوریشن اس کی سطح ٹھیک نہیں کر سکتی۔</p>\n<p>اپنے براؤزر میں <a href=\"/ur/tasveer-ki-saturation-badlein/\">Image Saturation Editor</a> کھولیں۔ سب کچھ مقامی طور پر چلتا ہے، اس لیے آپ کی تصویر کبھی سرور پر اپ لوڈ نہیں ہوتی۔</p>\n<h2 id=\"step-by-step\">پانچ مراحل میں سیچوریشن درست کریں</h2>\n<p>تصویر، اسکرین شاٹ یا اسکین شدہ تصویر کے لیے طریقہ ایک ہی ہے۔ اپ لوڈ کریں، درست کریں، رنگ دیکھیں، ایکسپورٹ کریں اور ڈاؤن لوڈ کی تصدیق کریں۔</p>\n<p>سلائیڈر کے ساتھ وقت لیں۔ چھوٹی حرکت بھی بڑا فرق ڈالتی ہے، اور پری ویو بالکل بتا دیتا ہے کہ رنگ کب درست لگتے ہیں۔</p>\n<p>استعمال سے پہلے ڈاؤن لوڈ شدہ فائل ایک بار کھولیں۔ تصدیق کریں کہ رنگ قدرتی اور رنگین لگیں، نہ کہ نیون یا نارنجی۔</p>\n<h2 id=\"using-the-slider\">سیچوریشن والا سلائیڈر کیسے استعمال کریں</h2>\n<p>سلائیڈر منفی سو سے جمع سو فیصد تک چلتا ہے، جہاں صفر کا مطلب کوئی تبدیلی نہیں۔ دائیں کھینچنے سے رنگ بڑھتے ہیں اور بائیں کھینچنے سے کم ہوتے ہیں۔</p>\n<p>آہستہ کھینچیں اور پری ویو دیکھتے رہیں۔ براہ راست اپ ڈیٹ بالکل دکھاتا ہے کہ رنگ کیسے بدلتے ہیں، اس لیے اسی مقام پر رک جائیں جہاں تصویر قدرتی لگے۔</p>\n<p>چھوٹی تبدیلیاں بڑی سے بہتر ہوتی ہیں۔ دس سے پچیس فیصد کی تبدیلی اکثر کافی ہوتی ہے، اور بڑی تبدیلی رنگوں کو جلد مصنوعی بنا دیتی ہے۔</p>\n<p>اپ لوڈ کے فوراً بعد ٹول آپ کی تصویر کو جمع پچیس فیصد پر دکھاتا ہے۔ یہ ابتدائی نقطہ فوراً بتاتا ہے کہ مناسب سیچوریشن کیسی لگتی ہے۔</p>\n<h2 id=\"using-quick-presets\">فوری پری سیٹس کیسے استعمال کریں</h2>\n<p>ٹول میں ایک کلک والے پری سیٹس ہیں جو عام سیچوریشن کی اقدار فوراً لگا دیتے ہیں۔ یہ سلائیڈر کھینچے بغیر مختلف انداز جانچنے کا تیز طریقہ ہیں۔</p>\n<p>منفی چالیس فیصد والا میوٹڈ پری سیٹ رنگوں کو نرم کر کے پرسکون، شاندار انداز دیتا ہے۔ منفی سو فیصد والا گرے اسکیل تمام رنگ ہٹا کر تصویر کو سیاہ سفید بنا دیتا ہے۔</p>\n<p>جمع نوے فیصد والا ہائپر پری سیٹ رنگوں کو حد تک بڑھا دیتا ہے۔ یہ پوسٹرز اور طرز والے گرافکس کے لیے موزوں ہے، مگر قدرتی فوٹوگرافی کے لیے شاذ ہی موزوں ہوتا ہے۔</p>\n<p>کسی پری سیٹ پر کلک کریں اور پری ویو دیکھیں۔ اگر نتیجہ قریب ہو مگر بالکل درست نہ ہو، تو وہیں سے سلائیڈر سے باریک درستی کر لیں۔</p>\n<h2 id=\"boosting-a-dull-photo\">پھیکی تصویر کے رنگ بڑھانا</h2>\n<p>پھیکی تصویر اپ لوڈ کریں اور سلائیڈر کو جمع بیس فیصد تک لے جائیں۔ پری ویو دیکھیں: رنگ بھرپور لگنے چاہئیں، سبز گہرے اور آسمان نیلا، بغیر مصنوعی لگے۔</p>\n<p>اگر تصویر اب بھی پھیکی ہو تو سلائیڈر کو پانچ فیصد کے چھوٹے قدموں میں بڑھائیں۔ ہر قدم تھوڑی سی رنگینی بڑھاتا ہے، اور پری ویو بتاتا ہے کہ کب رکنا ہے۔</p>\n<p>آگے بڑھتے ہوئے پتے اور گھاس پر نظر رکھیں۔ گھاس اور پتے سب سے پہلے نیون بنتے ہیں، اور چمکتی سبز کھیتوں والی لینڈ سکیپ مصنوعی لگتی ہے۔</p>\n<p>اگر بڑھانے کے بعد تصویر تیز لگے تو سلائیڈر پانچ فیصد کم کریں۔ چھوٹی کمی اکثر قدرتی انداز واپس لے آتی ہے، بغیر رنگینی کھوئے۔</p>\n<h2 id=\"muting-a-harsh-photo\">تیز رنگ والی تصویر کو نرم کرنا</h2>\n<p>جس تصویر کے رنگ بہت زیادہ مضبوط ہوں، اس کے لیے سلائیڈر کو بائیں کھینچیں۔ منفی بیس یا منفی چالیس فیصد جیسی منفی اقدار رنگوں کو پرسکون انداز میں نرم کر دیتی ہیں۔</p>\n<p>نرم کرتے وقت جلد دیکھتے رہیں۔ چہرہ قدرتی اور نرم لگنا چاہیے، نہ کہ بھورا اور بے جان، اس لیے رنگ مکمل ختم ہونے سے پہلے رک جائیں۔</p>\n<p>نرم کرنا شادیوں، پورٹریٹس اور فائن آرٹ کے لیے موزوں ہے، جہاں نرم رنگوں کا انداز شاندار لگتا ہے۔ نرم رنگوں والی تصویر نفیس لگتی ہے، جبکہ تیز رنگ والی بے ترتیب لگتی ہے۔</p>\n<p>مکمل بے رنگ انداز کے لیے منفی سو فیصد والا گرے اسکیل پری سیٹ استعمال کریں۔ تصویر سیاہ سفید بن جاتی ہے، جو ڈرامائی مناظر اور لازوال پورٹریٹس کے لیے موزوں ہے۔</p>\n<h2 id=\"converting-to-grayscale\">ایک کلک میں گرے اسکیل میں بدلنا</h2>\n<p>گرے اسکیل پری سیٹ پر کلک کریں تاکہ ایک ہی قدم میں تصویر سے تمام رنگ ہٹ جائیں۔ تصویر سیاہ سفید بن جاتی ہے اور صرف چمک اور کنٹراسٹ باقی رہ جاتے ہیں۔</p>\n<p>گرے اسکیل ڈرامائی مناظر، عمارتوں اور گلی کی فوٹوگرافی کے لیے موزوں ہے، جہاں شکل اور روشنی رنگ سے زیادہ اہم ہوتی ہے۔ یہ مضبوط تاثرات والی پورٹریٹس کے لیے بھی موزوں ہے۔</p>\n<p>بدلنے کے بعد کنٹراسٹ دیکھیں۔ گرے اسکیل تصویر کو اکثر کنٹراسٹ کا تھوڑا سا اضافہ چاہیے، کیونکہ رنگ وہ گہرائی لے جا چکا ہوتا ہے جو اب غائب ہے۔</p>\n<p>گرے اسکیل تصویروں کو اعلیٰ معیار کے ساتھ جے پی جی میں ایکسپورٹ کریں، یا تیز ترین نتیجے کے لیے پی این جی میں۔ فارمیٹ سے زیادہ کنٹراسٹ اہم ہے، جو سیاہ سفید کی تعریف کرتا ہے۔</p>\n<h2 id=\"fixing-skin-tones\">جلد کے رنگ درست کرنا</h2>\n<p>جلد سیچوریشن کے لیے سب سے مشکل چیز ہے۔ تھوڑا سا اضافہ پورٹریٹ کو صحت مند بنا سکتا ہے، مگر بڑا اضافہ جلد کو نارنجی، سرخ یا پیلا کر دیتا ہے۔</p>\n<p>پورٹریٹس کے لیے دس سے پندرہ فیصد کے تھوڑے اضافے سے شروع کریں۔ چہرہ دیکھیں: جلد گرم اور قدرتی لگنی چاہیے، نہ کہ جیسے شخص دھوپ میں بہت دیر رہا ہو۔</p>\n<p>گالوں اور پیشانی پر نظر رکھیں، جو زیادہ سیچوریشن سب سے پہلے دکھاتے ہیں۔ نارنجی گالوں اور پیلی پیشانی والا چہرہ حد سے زیادہ بڑھا ہوا ہوتا ہے۔</p>\n<p>اگر بڑھانے کے بعد جلد نارنجی لگے تو سلائیڈر پانچ فیصد کم کریں اور دوبارہ دیکھیں۔ چھوٹی کمی اکثر صحت مند انداز کھوئے بغیر قدرتی رنگ واپس لے آتی ہے۔</p>\n<h2 id=\"previewing\">ڈاؤن لوڈ سے پہلے پری ویو</h2>\n<p>ڈاؤن لوڈ سے پہلے ہمیشہ پری ویو دیکھیں۔ جانچیں کہ رنگ قدرتی لگیں، کوئی حصہ نیون نہ بن گیا ہو اور جلد کے رنگ نارنجی کے بجائے گرم ہوں۔</p>\n<p>پتوں، آسمان اور جلد کو مکمل سائز میں زوم کر کے دیکھیں۔ یہ حصے زیادہ سیچوریشن سب سے پہلے دکھاتے ہیں، اور چھوٹا پری ویو مسئلہ چھپا سکتا ہے۔</p>\n<p>اگر ممکن ہو تو تصویر دوسری اسکرین پر دیکھیں۔ مختلف ڈسپلے پر رنگ مختلف لگتے ہیں، اور دوسری جانچ بانٹنے سے پہلے حیرانی پکڑ لیتی ہے۔</p>\n<p>اگر کوئی رنگ مصنوعی لگے تو سلائیڈر پانچ فیصد کم کریں اور دوبارہ دیکھیں۔ چھوٹی کمی اکثر رنگینی کھوئے بغیر قدرتی انداز واپس لے آتی ہے۔</p>\n<h2 id=\"choosing-export-format\">ایکسپورٹ فارمیٹ کا انتخاب</h2>\n<p>بانٹنے والی تصویروں کے لیے جے پی جی چنیں۔ یہ فائل کا حجم چھوٹا رکھتا ہے، ہر جگہ کام کرتا ہے اور اعلیٰ معیار کی سیٹنگ رنگوں کو صاف رکھتی ہے۔</p>\n<p>شفافیت والے گرافکس اور اسٹیکرز کے لیے پی این جی چنیں۔ پی این جی نقصان سے پاک ہے، اس لیے رنگ بالکل درست رہتے ہیں اور شفاف حصے بچ جاتے ہیں۔</p>\n<p>چھوٹی فائل اور اچھا معیار چاہتے ہوں تو ویب پی چنیں۔ یہ ویب تصاویر کے لیے اچھا کام کرتا ہے، اگرچہ چند پرانے نظام اب بھی اسے رد کر دیتے ہیں۔</p>\n<p>یاد رکھیں کہ پی این جی کے لیے معیار والا سلائیڈر چھپ جاتا ہے، کیونکہ پی این جی نقصان سے پاک ہے اور اس کی کوئی معیار کی سیٹنگ نہیں ہوتی۔ یہ عام رویہ ہے، ٹول کا مسئلہ نہیں۔</p>\n<h2 id=\"adjusting-on-mobile\">فون یا ٹیبلٹ پر سیچوریشن درست کرنا</h2>\n<p>یہ ٹول ٹچ اسکرین پر کام کرتا ہے، اس لیے آپ پھیکی تصویر اسی فون پر ٹھیک کر سکتے ہیں جس سے وہ لی گئی ہو۔ گیلری سے اپ لوڈ کریں، سلائیڈر انگلی سے کھینچیں اور ڈاؤن لوڈ کریں۔</p>\n<p>انگلی سے سلائیڈر کھینچنا ماؤس سے کم درست ہوتا ہے۔ درست اقدار کے لیے فوری پری سیٹس استعمال کریں، پھر چھوٹی حرکتوں سے باریک درستی کریں۔</p>\n<p>ڈاؤن لوڈ سے پہلے پری ویو مکمل سائز میں دیکھیں۔ چھوٹی فون اسکرین پر ٹھیک لگنے والی تبدیلی کمپیوٹر پر بہت زیادہ نکل سکتی ہے۔</p>\n<p>ڈاؤن لوڈ شدہ فائلیں آپ کے معمول کے ڈاؤن لوڈ فولڈر میں جاتی ہیں۔ وہاں سے تبدیل شدہ تصویر کو براہ راست چیٹ ایپ، ای میل یا سوشل پوسٹ پر بانٹ سکتے ہیں۔</p>\n<h2 id=\"troubleshooting\">عام سیچوریشن کے مسائل کا حل</h2>\n<p>اگر تصویر تیز لگے تو سلائیڈر بہت اونچا ہے۔ اسے چھوٹے قدموں میں کم کریں، جب تک گھاس، آسمان اور جلد دوبارہ قدرتی نہ لگیں۔</p>\n<p>اگر بڑھانے کے بعد بھی تصویر پھیکی رہے تو اصل تصویر بہت زیادہ چپٹی ہو سکتی ہے۔ گھنی دھند سے لی گئی تصویر میں وہ رنگ نہیں آ سکتا جو کبھی قید ہی نہیں ہوا۔</p>\n<p>اگر جلد نارنجی لگے تو سیچوریشن کم کریں اور چہرہ مکمل سائز میں دیکھیں۔ چھوٹی کمی عام طور پر قدرتی رنگ واپس لے آتی ہے۔</p>\n<p>اگر پری ویو ڈاؤن لوڈ سے مختلف لگے تو ایکسپورٹ فارمیٹ اور معیار دیکھیں۔ جے پی جی کی کم معیار کی سیٹنگ رنگوں کو ہلکا سا بدل سکتی ہے، خاص طور پر روشن حصوں میں۔</p>\n<h2 id=\"saturation-plus-contrast\">سیچوریشن اور کنٹراسٹ: عام جوڑی</h2>\n<p>جو تصویر پھیکی اور چپٹی دونوں ہو، اسے سیچوریشن اور کنٹراسٹ دونوں چاہئیں۔ پہلے رنگ بڑھائیں، پھر کنٹراسٹ شامل کریں تاکہ گہرائی واپس آئے۔</p>\n<p>رنگ بڑھانے کے بعد اگر تصویر رنگین مگر پھر بھی چپٹی لگے تو <a href=\"/ur/tasveer-ka-contrast-badlein/\">Image Contrast Editor</a> استعمال کریں۔ تھوڑا سا کنٹراسٹ سائے اور روشن حصے واپس لاتا ہے۔</p>\n<p>مراحل اسی ترتیب میں کریں: پہلے سیچوریشن، پھر کنٹراسٹ۔ الٹی ترتیب سے رنگ کی تبدیلی کا اندازہ مشکل ہو جاتا ہے، کیونکہ تصویر اب بھی چپٹی ہوتی ہے۔</p>\n<p>ہر مرحلے کے بعد رنگ دوبارہ دیکھیں۔ کنٹراسٹ کا اضافہ رنگوں کو بھی بھرپور بناتا ہے، اس لیے سیچوریشن کو بعد میں تھوڑا کم کرنا پڑ سکتا ہے۔</p>\n<h2 id=\"saturation-for-social\">سوشل میڈیا کے لیے سیچوریشن</h2>\n<p>سوشل فیڈز رنگین، صاف تصویروں کو پسند کرتی ہیں۔ پھیکی تصویر کو اسکرول کر کے گزر جاتے ہیں، جبکہ اچھی رنگین تصویر انگوٹھا روک لیتی ہے اور دوسری نظر کماتی ہے۔</p>\n<p>سوشل تصویروں کو پرنٹ کے مقابلے میں تھوڑا زیادہ بڑھائیں۔ اسکرینوں کے رنگ مختلف ہوتے ہیں، اور آپ کے فون پر ٹھیک لگنے والی تصویر کسی اور کی اسکرین پر پھیکی لگ سکتی ہے۔</p>\n<p>اضافہ قدرتی رکھیں۔ بہت زیادہ بڑھی ہوئی تصویر مصنوعی لگتی ہے، اور فالوورز بتا سکتے ہیں کہ رنگ منظر سے میل نہیں کھاتے۔</p>\n<p>پوسٹ کرنے سے پہلے رنگین تصویر کو فیڈ کے سائز میں جانچیں۔ مکمل سائز میں اچھی لگنے والی تصویر چھوٹے پری ویو میں بہت پھیکی یا بہت تیز نکل سکتی ہے، اس لیے پہلے دیکھیں۔</p>\n<h2 id=\"saving-settings\">اگلی بار کے لیے سیٹنگز محفوظ کرنا</h2>\n<p>ملتی جلتی تصویروں کے لیے کام کرنے والی سیچوریشن کی قدر لکھ لیں۔ لینڈ سکیپس کے لیے جمع بیس فیصد جیسی مختصر نوٹ اگلی بار اندازہ لگانے سے بچاتی ہے۔</p>\n<p>ایک ہی روشنی میں لی گئی تصویروں کے بیچ کے لیے ایک ہی قدر استعمال کریں۔ پورے سیٹ میں مستقل رنگ پیشہ ورانہ لگتا ہے، جبکہ ملی جلی قدریں بے ترتیب لگتی ہیں۔</p>\n<p>اصل فائلیں رکھیں۔ ایک تصویر کے لیے کام کرنے والی سیچوریشن کی قدر دوسری کے لیے موزوں نہ ہو، اور اصل فائل سے آپ بغیر اضافی نقصان کے دوسری سطح آزما سکتے ہیں۔</p>\n<p>اپنی نوٹس کبھی کبھار دیکھتے رہیں۔ جیسے جیسے آپ کا کیمرہ اور روشنی بہتر ہوتی ہے، درکار سیچوریشن کی قدریں بھی بدلتی ہیں اور پرانی نوٹس گمراہ کر سکتی ہیں۔</p>\n<h2 id=\"quick-tips\">بہتر سیچوریشن کے لیے فوری نکات</h2>\n<p>چھوٹے قدموں میں درست کریں۔ ایک وقت میں پانچ فیصد کی تبدیلی آپ کو قابو دیتی ہے، جبکہ بڑی چھلانگ درست قدر سے آگے نکل سکتی ہے۔</p>\n<p>صرف منظر نہیں، جلد بھی دیکھیں۔ گھاس پر ٹھیک لگنے والا اضافہ تصویر میں موجود لوگوں کو نارنجی بنا سکتا ہے۔</p>\n<p>پری سیٹس کو نقطہ آغاز سمجھیں۔ پری سیٹ فوری آزمائش دیتا ہے، اور سلائیڈر سے آپ وہیں سے باریک درستی کر سکتے ہیں۔</p>\n<p>اصل تصویر بغیر تبدیلی کے محفوظ کریں۔ ایک بار سیچوریشن کی تبدیلی ایکسپورٹ میں شامل ہو جائے تو اس فائل سے واپس نہیں ہو سکتی۔</p>\n<h2 id=\"saturation-for-sunset\">غروب آفتاب کی تصویر کے لیے سیچوریشن</h2>\n<p>غروب آفتاب کی تصویریں پہلے ہی رنگین ہوتی ہیں، اس لیے انہیں صرف تھوڑا سا اضافہ چاہیے۔ دس سے پندرہ فیصد کی سیچوریشن نارنجی اور گلابی رنگ گہرے کر دیتی ہے، بغیر انہیں مصنوعی بنائے۔</p>\n<p>بڑھاتے وقت آسمان کی تدریج دیکھیں۔ غروب کا آسمان نارنجی سے گلابی اور پھر نیلے کی طرف ہموار ہونا چاہیے، اور مضبوط اضافہ اس تدریج کو چپٹے بلاکس میں بدل سکتا ہے۔</p>\n<p>بڑھانے کے بعد اگلا حصہ دیکھیں۔ رنگ بڑھے ہوئے اندھیرے اگلے حصے کے ساتھ تصویر کیچڑ جیسی لگ سکتی ہے، اس لیے اگر غروب ہی اصل موضوع ہو تو پہلے اسے ہلکا سا روشن کریں۔</p>\n<p>پانی پر غروب کے لیے مناسب اضافہ عکس کو بڑھاتا ہے، بغیر اسے تیز بنائے۔ پانی کو آسمان کی عکس دکھانی چاہیے، اس سے مقابلہ نہیں کرنا چاہیے۔</p>\n<p>موازنے کے لیے <a href=\"/ur/blog/saturation-vs-vibrance/\">Saturation vs Vibrance: Natural Colour Editing</a> پڑھیں۔ مکمل جائزے کے لیے <a href=\"/ur/blog/tasveer-saturation-editor-rehnumai/\">Image Saturation Editor: Complete Guide</a> دیکھیں، اور مستقل انداز کے لیے <a href=\"/ur/tasveer-filters/\">Image Filters</a> ٹول شامل کریں۔</p>\n<ul>\n<li>اپنی تصویر ڈراپ زون میں کھینچ کر، ڈیوائس سے چن کر، یا کنٹرول اور وی دبا کر اسکرین شاٹ چپکا کر اپ لوڈ کریں۔</li>\n<li>رنگ بڑھانے کے لیے سیچوریشن لیول سلائیڈر کو دائیں اور کم کرنے کے لیے بائیں کھینچیں، براہ راست پری ویو دیکھتے ہوئے۔</li>\n<li>ایک کلک کی آزمائش کے لیے میوٹڈ، گرے اسکیل یا ہائپر جیسا فوری پری سیٹ آزمائیں، پھر سلائیڈر سے باریک درستی کریں۔</li>\n<li>جلد کے رنگ، پتے اور آسمان کو مکمل سائز میں دیکھیں تاکہ کوئی رنگ مصنوعی نہ لگے۔</li>\n<li>ایکسپورٹ فارمیٹ اور معیار چنیں، پھر درست شدہ تصویر محفوظ کرنے کے لیے ڈاؤن لوڈ پر کلک کریں۔</li>\n</ul>";

export const FAQS: BlogArticleFaq[] = [{"question":"میں اپنے فون پر تصویر کے رنگ کیسے بڑھاؤں؟","answer":"اپنے فون کے براؤزر میں Image Saturation Editor کھولیں، گیلری سے تصویر اپ لوڈ کریں اور انگلی سے سلائیڈر کو دائیں کھینچیں۔ درست قدر کے لیے فوری پری سیٹ استعمال کریں، جلد کے رنگ دیکھیں اور پھر ڈاؤن لوڈ کریں۔"},{"question":"لینڈ سکیپ فوٹو کے لیے کون سی سیچوریشن کی قدر استعمال کروں؟","answer":"جمع بیس فیصد سے شروع کریں اور پتے دیکھیں۔ لینڈ سکیپس کو عام طور پر رنگین لگنے کے لیے بیس سے تیس فیصد چاہیے۔ گھاس نیون بننے یا آسمان پینٹ جیسا لگنے سے پہلے رک جائیں، اور رنگ تیز ہوں تو سلائیڈر کم کریں۔"},{"question":"میں رنگین تصویر کو سیاہ سفید کیسے بناؤں؟","answer":"گرے اسکیل پری سیٹ پر کلک کریں، جو سیچوریشن کو منفی سو فیصد کر کے ایک ہی قدم میں تمام رنگ ہٹا دیتا ہے۔ بعد میں کنٹراسٹ دیکھیں، کیونکہ گرے اسکیل تصویر کو اکثر کنٹراسٹ کا تھوڑا سا اضافہ چاہیے۔"},{"question":"سیچوریشن بڑھانے کے بعد میری کھانے کی تصویر جعلی کیوں لگتی ہے؟","answer":"سلائیڈر بہت اونچا ہے، جس سے سرخ غیر فطری طور پر چمکدار اور سبز نیون بن جاتے ہیں۔ کھانے کو صرف دس سے بیس فیصد کا تھوڑا سا اضافہ چاہیے۔ سلائیڈر کم کریں، جب تک کھانا تازہ اور بھوک لگانے والا نہ لگے۔"},{"question":"کیا سیچوریشن کنٹراسٹ سے پہلے درست کروں یا بعد میں؟","answer":"پہلے سیچوریشن، پھر کنٹراسٹ۔ رنگ بڑھانا تصویر کا احساس بدلتا ہے اور کنٹراسٹ بعد میں گہرائی کو بہتر بناتا ہے۔ کنٹراسٹ کی تبدیلی کے بعد رنگ دوبارہ دیکھیں، کیونکہ وہ انہیں بھرپور بناتا ہے۔"},{"question":"کیا میں ڈاؤن لوڈ کے بعد سیچوریشن کی تبدیلی واپس کر سکتا ہوں؟","answer":"ڈاؤن لوڈ شدہ فائل سے نہیں، کیونکہ تبدیلی ایکسپورٹ میں شامل ہو جاتی ہے۔ اصل تصویر رکھیں تاکہ آپ دوسری سیچوریشن کی سطح آزما سکیں۔ ٹول میں، ڈاؤن لوڈ سے پہلے صفر پر واپس جانے کے لیے ری سیٹ کا آپشن استعمال کریں۔"}];
